INSERT INTO `risk_rule` (`rule_id`, `rule_key`, `rule_name`, `description`, `rule_type`, `threshold_value`, `threshold_unit`, `config_json`, `risk_level`, `need_manual_review`, `enabled`, `update_time`) VALUES (1,'EXACT_DUPLICATE','完全相同文件','证书文件SHA-256完全相同（非同团队成员）时触发','flag',NULL,NULL,NULL,'high',1,1,'2026-10-04 13:49:04'),(2,'PHASH_SIMILAR','pHash相似度阈值','证书图片感知哈希相似度达到阈值（非同团队成员）时触发','threshold',0.90,'相似度0~1，越大越严格',NULL,'high',1,1,'2026-10-04 13:49:04'),(3,'NAME_MISMATCH','姓名不一致','OCR识别姓名与申报人姓名不一致时触发','flag',NULL,NULL,NULL,'high',1,1,'2026-10-04 13:49:04'),(4,'AWARD_MISMATCH','奖项不一致','OCR识别获奖等级与申报获奖等级不一致时触发','flag',NULL,NULL,NULL,'medium',1,1,'2026-10-04 13:49:04'),(5,'TIME_MISMATCH','时间不一致','OCR识别获奖时间与申报获奖时间不一致时触发','flag',NULL,NULL,NULL,'medium',1,1,'2026-10-04 13:49:04'),(6,'CERT_NO_DUPLICATE','证书编号重复','OCR识别的证书编号与其他申请重复时触发','flag',NULL,NULL,NULL,'high',1,1,'2026-10-04 13:49:04'),(7,'OCR_LOW_CONFIDENCE','OCR识别置信度阈值','OCR整体置信度低于阈值或识别失败时触发（转人工审核）','threshold',0.80,'置信度0~1',NULL,'medium',1,1,'2026-10-04 13:49:04'),(8,'OCR_COMPARE_FIELDS','OCR比对字段配置','控制OCR预检参与比对的申报字段','flag',NULL,NULL,'[\"name\",\"competition\",\"awardLevel\",\"awardTime\"]','low',0,1,'2026-10-04 13:49:04');
